#include <stack>
#include <vector>
#include <deque>

int main() {
    // 1. Default stack (uses deque)
    std::stack<int> s_default;

    // 2. Stack based on vector (reallocation risk)
    std::stack<int, std::vector<int>> s_vec;

    // 3. Stack based on list (memory overhead)
    std::stack<int, std::list<int>> s_list;

    // All three provide O(1) push/pop, but guarantee different worst-case times
    s_default.push(5);
    s_vec.push(5);
    s_list.push(5);
}
